-- Posição de estoque DELLA ESTOQUE (10/11/2026): SKUs iguais ao controle de estoque, entrada das quantidades,
-- reativação de Carmesim, Mirras e Letrinhas (preço de teste R$ 1,00 onde não houver preço) e fotos dos produtos.
UPDATE "brands" SET "active" = true, "updatedAt" = now() WHERE "name" IN ('Carmesim', 'Mirras', 'Letrinhas');
UPDATE "categories" SET "name" = 'Pinças Caneladas', "updatedAt" = now()
 WHERE "name" = 'Pinças Douradas' AND NOT EXISTS (SELECT 1 FROM "categories" WHERE "name" = 'Pinças Caneladas');
UPDATE "products" SET "sku" = 'BAR-001-CA049', "active" = true,
       "priceCents" = CASE WHEN "priceCents" > 0 THEN "priceCents" ELSE 100 END, "updatedAt" = now()
 WHERE "sku" = 'CA049' AND NOT EXISTS (SELECT 1 FROM "products" WHERE "sku" = 'BAR-001-CA049');
