WITH e(sku,qtd) AS (VALUES ('BAR-001-CA049',20),('BAR-002-CA050',24),('BAR-003-CA051',24),('BAR-004-CA052',36),('BAR-005-CA053',35),('POM-004-CA054',20),('POM-006-CA056',36),('PAS-001-CA075',48),('CER-002-CA076',47),('POM-005-CA078',45),('PAS-002-CA092',46),('CER-001-MI071',36),('POM-001-MI072',2),('POM-002-MI073',15),('POM-003-MI108',36),('GEL-002-LE001',47),('GEL-003-LE002',46),('GEL-004-LE003',48),('GEL-005-LE004',47),('PIN-INX-PFI-006-2271504',29),('PIN-INX-OBL-004-2260504',44),('PIN-INX-RET-005-2264504',44),('PIN-LAQ-PFI-009-2291504',101),('PIN-LAQ-OBL-007-2280504',47),('PIN-LAQ-RED-008-2284504',47),('PIN-CAN-PFI-003-2321303',182),('PIN-CAN-OBL-001-2311303',134),('PIN-CAN-RET-002-2341303',134),('NAV-INX-STD-001-3011548',42)),
alvo AS (SELECT p."id", e.qtd, p."stockQty", p."reservedQty" FROM e JOIN "products" p ON p."sku"=e.sku
         WHERE NOT EXISTS (SELECT 1 FROM "stock_movements" m WHERE m."dedupeKey"='posicao-estoque-20261110:'||p."id")),
mov AS (INSERT INTO "stock_movements" ("id","productId","type","quantity","stockAfter","reservedAfter","reason","dedupeKey","userId","createdAt")
  SELECT gen_random_uuid(),a."id",'IN',a.qtd,a."stockQty"+a.qtd,a."reservedQty",'Entrada conforme posição de estoque DELLA ESTOQUE de 10/11/2026',
         'posicao-estoque-20261110:'||a."id",(SELECT u."id" FROM "users" u WHERE u."role"='ADMIN' ORDER BY u."createdAt" LIMIT 1),now()
    FROM alvo a WHERE a.qtd > 0 AND EXISTS (SELECT 1 FROM "users" u WHERE u."role"='ADMIN') RETURNING "productId","quantity")
UPDATE "products" p SET "stockQty"=p."stockQty"+mov."quantity","updatedAt"=now() FROM mov WHERE p."id"=mov."productId";
